package conditionifstatement;

public class elseifladder {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
   int a = 10;  // multiple  condition use 
   if(a>10 ) {
	   System.out.println("gratter then 10"); 
   } else if (a == 10) {
	   System.out.println("Equel to 10");
   } else {
	   System.out.println("less then 10");
   }
	}
}
